def pivot_index(nums):
    total = sum(nums)
    lefts = []
    running = 0
    for x in nums:
        lefts.append(running)
        running += x
    for i in range(len(nums)):
        if lefts[i] == total - lefts[i] - nums[i]:
            return i
    return -1

print(pivot_index(nums))

